/*
 * JJCORETECH Audit Charts
 * Lightweight local chart renderer
 * Supports: bar and pie charts
 */

(function (window) {

    "use strict";

    function Chart(canvas, config) {

        if (!canvas) {
            return;
        }

        this.canvas = canvas;
        this.config = config || {};
        this.ctx = canvas.getContext("2d");

        if (!this.ctx) {
            return;
        }

        this.resize();

        if (this.config.type === "bar") {
            this.drawBar();
        }

        if (this.config.type === "pie") {
            this.drawPie();
        }
    }


    /* ========================= */
    /* RESIZE CANVAS */
    /* ========================= */

    Chart.prototype.resize = function () {

        var rect = this.canvas.getBoundingClientRect();

        var width = rect.width || 600;
        var height = rect.height || 300;

        if (width < 300) {
            width = 600;
        }

        if (height < 200) {
            height = 300;
        }

        this.canvas.width = width;
        this.canvas.height = height;

        this.width = width;
        this.height = height;
    };


    /* ========================= */
    /* BAR CHART */
    /* ========================= */

    Chart.prototype.drawBar = function () {

        var ctx = this.ctx;
        var width = this.width;
        var height = this.height;

        var data = this.config.data || {};

        var labels = data.labels || [];

        var datasets = data.datasets || [];

        if (!datasets.length) {
            return;
        }

        var values = datasets[0].data || [];

        if (!values.length) {
            return;
        }


        ctx.clearRect(
            0,
            0,
            width,
            height
        );


        /* ========================= */
        /* CHART AREA */
        /* ========================= */

        var left = 55;
        var right = 25;
        var top = 30;
        var bottom = 55;

        var chartWidth =
            width - left - right;

        var chartHeight =
            height - top - bottom;


        /* ========================= */
        /* FIND MAXIMUM */
        /* ========================= */

        var max = 0;

        var i;

        for (i = 0; i < values.length; i++) {

            if (Number(values[i]) > max) {
                max = Number(values[i]);
            }

        }

        if (max < 1) {
            max = 1;
        }

        max = Math.ceil(max);


        /* ========================= */
        /* GRID + Y AXIS */
        /* ========================= */

        ctx.font = "12px Arial";
        ctx.textAlign = "right";
        ctx.textBaseline = "middle";

        for (i = 0; i <= max; i++) {

            var y =
                top +
                chartHeight -
                (i / max) * chartHeight;

            ctx.beginPath();

            ctx.moveTo(left, y);

            ctx.lineTo(
                width - right,
                y
            );

            ctx.strokeStyle = "#dddddd";

            ctx.stroke();

            ctx.fillStyle = "#555555";

            ctx.fillText(
                String(i),
                left - 8,
                y
            );
        }


        /* ========================= */
        /* AXES */
        /* ========================= */

        ctx.beginPath();

        ctx.moveTo(left, top);

        ctx.lineTo(left, height - bottom);

        ctx.lineTo(
            width - right,
            height - bottom
        );

        ctx.strokeStyle = "#555555";

        ctx.stroke();


        /* ========================= */
        /* BARS */
        /* ========================= */

        var barSpace =
            chartWidth / values.length;

        var barWidth =
            barSpace * 0.55;


        for (i = 0; i < values.length; i++) {

            var value =
                Number(values[i]) || 0;

            var barHeight =
                (value / max) * chartHeight;

            var x =
                left +
                (i * barSpace) +
                ((barSpace - barWidth) / 2);

            var y =
                top +
                chartHeight -
                barHeight;


            ctx.fillStyle = "#4285f4";

            ctx.fillRect(
                x,
                y,
                barWidth,
                barHeight
            );


            /* VALUE */

            ctx.fillStyle = "#333333";

            ctx.textAlign = "center";

            ctx.textBaseline = "bottom";

            ctx.fillText(
                String(value),
                x + barWidth / 2,
                y - 5
            );


            /* LABEL */

            ctx.fillStyle = "#333333";

            ctx.textBaseline = "top";

            var label =
                labels[i] !== undefined
                    ? String(labels[i])
                    : "";

            ctx.fillText(
                label,
                x + barWidth / 2,
                height - bottom + 10
            );
        }


        /* ========================= */
        /* TITLE */
        /* ========================= */

        if (
            datasets[0].label
        ) {

            ctx.font =
                "bold 14px Arial";

            ctx.textAlign =
                "left";

            ctx.textBaseline =
                "top";

            ctx.fillStyle =
                "#333333";

            ctx.fillText(
                datasets[0].label,
                left,
                8
            );
        }
    };


    /* ========================= */
    /* PIE CHART */
    /* ========================= */

    Chart.prototype.drawPie = function () {

        var ctx = this.ctx;

        var width = this.width;
        var height = this.height;

        var data = this.config.data || {};

        var labels =
            data.labels || [];

        var datasets =
            data.datasets || [];

        if (!datasets.length) {
            return;
        }

        var values =
            datasets[0].data || [];

        if (!values.length) {
            return;
        }


        ctx.clearRect(
            0,
            0,
            width,
            height
        );


        /* ========================= */
        /* TOTAL */
        /* ========================= */

        var total = 0;

        var i;

        for (i = 0; i < values.length; i++) {

            total +=
                Number(values[i]) || 0;
        }

        if (total <= 0) {
            return;
        }


        /* ========================= */
        /* PIE POSITION */
        /* ========================= */

        var centerX =
            width * 0.38;

        var centerY =
            height * 0.50;

        var radius =
            Math.min(
                width * 0.28,
                height * 0.38
            );


        var startAngle =
            -Math.PI / 2;


        /* ========================= */
        /* PIE SLICES */
        /* ========================= */

        var sliceColors = [
            "#4285f4",
            "#34a853",
            "#fbbc05",
            "#ea4335",
            "#9c27b0",
            "#00acc1",
            "#ff7043",
            "#8d6e63"
        ];


        for (i = 0; i < values.length; i++) {

            var value =
                Number(values[i]) || 0;

            var sliceAngle =
                (value / total) *
                Math.PI * 2;

            var endAngle =
                startAngle +
                sliceAngle;


            ctx.beginPath();

            ctx.moveTo(
                centerX,
                centerY
            );

            ctx.arc(
                centerX,
                centerY,
                radius,
                startAngle,
                endAngle
            );

            ctx.closePath();


            ctx.fillStyle =
                sliceColors[
                    i % sliceColors.length
                ];

            ctx.fill();


            ctx.strokeStyle =
                "#ffffff";

            ctx.lineWidth = 2;

            ctx.stroke();


            startAngle =
                endAngle;
        }


        /* ========================= */
        /* LEGEND */
        /* ========================= */

        var legendX =
            width * 0.68;

        var legendY = 40;


        ctx.font =
            "13px Arial";

        ctx.textAlign =
            "left";

        ctx.textBaseline =
            "middle";


        for (i = 0; i < labels.length; i++) {

            var y =
                legendY +
                (i * 28);


            ctx.fillStyle =
                sliceColors[
                    i % sliceColors.length
                ];


            ctx.fillRect(
                legendX,
                y - 8,
                16,
                16
            );


            ctx.fillStyle =
                "#333333";


            ctx.fillText(
                String(labels[i]),
                legendX + 24,
                y
            );
        }
    };


    /* ========================= */
    /* EXPOSE CHART */
    /* ========================= */

    window.Chart = Chart;

})(window);